17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.LinkedHashMap;
20	import java.util.Map;
21	
22	import org.springframework.samples.petclinic.rest.error.InvalidTelephoneException;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Normalizes a submitted telephone number into E.164 form. A leading '+' and country code are kept
27	 * when present; otherwise the default country code '+61' is assumed and a single leading '0' is
28	 * dropped from the national digits. Spaces, dashes and brackets are stripped, and the result must
29	 * hold between 8 and 15 digits after the '+'. For known country codes the national number must also
30	 * be exactly the length that country requires ('+61' => 9 national digits, '+1' => 10).
31	 */
32	@Component
33	public class TelephoneNormalizer {
34	
35	    private static final String DEFAULT_COUNTRY_CODE = "61";
36	
37	    /** Characters used only for human-readable grouping and removed before parsing. */
38	    private static final String FORMATTING_CHARS = "[\\s\\-()\\[\\]]";
39	
40	    private static final int MIN_DIGITS = 8;
41	    private static final int MAX_DIGITS = 15;
42	
43	    /**
44	     * Required national-number length for each known country code, ordered longest prefix first so
45	     * the most specific country code is matched against a normalized number.
46	     */
47	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = new LinkedHashMap<>();
48	
49	    static {
50	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("61", 9);
51	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("1", 10);
52	    }
53	
54	    /**
55	     * @param telephone the raw, possibly formatted telephone number
56	     * @return the telephone in E.164 form (a '+' followed by 8 to 15 digits)
57	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
58	     */
59	    public String normalize(String telephone) {
60	        if (telephone == null) {
61	            throw new InvalidTelephoneException(null);
62	        }
63	        String cleaned = telephone.trim().replaceAll(FORMATTING_CHARS, "");
64	        String digits;
65	        if (cleaned.startsWith("+")) {
66	            digits = cleaned.substring(1);
67	        } else {
68	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
69	            digits = DEFAULT_COUNTRY_CODE + national;
70	        }
71	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
72	            throw new InvalidTelephoneException(telephone);
73	        }
74	        requireValidNationalLength(digits, telephone);
75	        return "+" + digits;
76	    }
77	
78	    /**
79	     * Rejects a normalized number whose national part is the wrong length for its country code. Only
80	     * known country codes are checked; a number with an unrecognised country code passes.
81	     */
82	    private void requireValidNationalLength(String digits, String telephone) {
83	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
84	            String countryCode = entry.getKey();
85	            if (digits.startsWith(countryCode)) {
86	                int nationalLength = digits.length() - countryCode.length();
87	                if (nationalLength != entry.getValue()) {
88	                    throw new InvalidTelephoneException(telephone);
89	                }
90	                return;
91	            }
92	        }
93	    }
94	}
