16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @Column(name = "possible_duplicate")
77	    private Boolean possibleDuplicate;
78	
79	    @Column(name = "possible_duplicate_of")
80	    private Integer possibleDuplicateOf;
81	
82	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
83	    private Set<Pet> pets;
84	
85	    public String getAddress() {
86	        return this.address;
87	    }
88	
89	    public void setAddress(String address) {
90	        this.address = address;
91	    }
92	
93	    public String getCity() {
94	        return this.city;
95	    }
96	
97	    public void setCity(String city) {
98	        this.city = city;
99	    }
100	
101	    public String getTelephone() {
102	        return this.telephone;
103	    }
104	
105	    public void setTelephone(String telephone) {
106	        this.telephone = telephone;
107	    }
108	
109	    public String getEmail() {
110	        return this.email;
111	    }
112	
113	    public void setEmail(String email) {
114	        this.email = email;
115	    }
116	
117	    public String getPostcode() {
118	        return this.postcode;
119	    }
120	
121	    public void setPostcode(String postcode) {
122	        this.postcode = postcode;
123	    }
124	
125	    public LocalDate getRegistrationDate() {
126	        return this.registrationDate;
127	    }
128	
129	    public void setRegistrationDate(LocalDate registrationDate) {
130	        this.registrationDate = registrationDate;
131	    }
132	
133	    public LocalDate getBirthDate() {
134	        return this.birthDate;
135	    }
136	
137	    public void setBirthDate(LocalDate birthDate) {
138	        this.birthDate = birthDate;
139	    }
140	
141	    public String getCustomerCode() {
142	        return this.customerCode;
143	    }
144	
145	    public void setCustomerCode(String customerCode) {
146	        this.customerCode = customerCode;
147	    }
148	
149	    public String getHouseholdId() {
150	        return this.householdId;
151	    }
152	
153	    public void setHouseholdId(String householdId) {
154	        this.householdId = householdId;
155	    }
156	
157	    public Integer getNamesakeCount() {
158	        return this.namesakeCount;
159	    }
160	
161	    public void setNamesakeCount(Integer namesakeCount) {
162	        this.namesakeCount = namesakeCount;
163	    }
164	
165	    public Integer getHouseholdSize() {
166	        return this.householdSize;
167	    }
168	
169	    public void setHouseholdSize(Integer householdSize) {
170	        this.householdSize = householdSize;
171	    }
172	
173	    /**
174	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
175	     * postcode while holding a different telephone. Resolved at creation and stored so it is
176	     * reported consistently on every later read.
177	     */
178	    public Boolean getPossibleDuplicate() {
179	        return this.possibleDuplicate;
180	    }
181	
182	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
183	        this.possibleDuplicate = possibleDuplicate;
184	    }
185	
186	    /**
187	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
188	     * is not a possible duplicate.
189	     */
190	    public Integer getPossibleDuplicateOf() {
191	        return this.possibleDuplicateOf;
192	    }
193	
194	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
195	        this.possibleDuplicateOf = possibleDuplicateOf;
196	    }
197	
198	    /**
199	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
200	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
201	     * email or household contributes an empty string. Two owners are duplicates only when their
202	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
203	     * different telephones have distinct identity keys and are both allowed.
204	     */
205	    public String getIdentityKey() {
206	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
207	    }
208	
209	    private static String orEmpty(String value) {
210	        return value == null ? "" : value;
211	    }
212	
213	    /**
214	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
215	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
216	     * from the owner's own fields; absent until both the customer code and registration date
217	     * have been assigned.
218	     */
219	    public String getMembershipNumber() {
220	        if (this.customerCode == null || this.registrationDate == null) {
221	            return null;
222	        }
223	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
224	    }
225	
226	    /**
227	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
228	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
229	     */
230	    public Integer getCheckDigit() {
231	        if (this.customerCode == null) {
232	            return null;
233	        }
234	        return Luhn.checkDigit(this.customerCode);
235	    }
236	
237	    /**
238	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields:
239	     * every owner starts at level 1, gains a level when an email address is present, and gains a
240	     * further level when this owner has no namesakes ({@code namesakeCount} is 0). The result is
241	     * capped at 3; level 4 is reserved for tenure.
242	     */
243	    public Integer getMembershipLevel() {
244	        int level = 1;
245	        boolean hasEmail = this.email != null && !this.email.isEmpty();
246	        if (hasEmail) {
247	            level++;
248	        }
249	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
250	        if (unique) {
251	            level++;
252	        }
253	        return Math.min(level, 3);
254	    }
255	
256	    /**
257	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
258	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
259	     * before a customer code has been assigned.
260	     */
261	    public String getLocality() {
262	        if (this.customerCode == null) {
263	            return Regions.UNKNOWN;
264	        }
265	        int separator = this.customerCode.indexOf('-');
266	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
267	    }
268	
269	    /**
270	     * The owner's preferred contact channel, derived from the owner's own fields:
271	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
272	     */
273	    public String getContactPreference() {
274	        boolean hasEmail = this.email != null && !this.email.isEmpty();
275	        return hasEmail ? "EMAIL" : "PHONE";
276	    }
277	
278	    /**
279	     * The owner's age band, derived from the owner's own fields: the whole years between
280	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
281	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
282	     * (65 or older). Absent until a birth date and a registration date are both present.
283	     */
284	    public String getAgeBand() {
285	        if (this.birthDate == null || this.registrationDate == null) {
286	            return null;
287	        }
288	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
289	        if (age < 18) {
290	            return "MINOR";
291	        }
292	        return age < 65 ? "ADULT" : "SENIOR";
293	    }
294	
295	    /**
296	     * Resolve the effective registration date before persisting: default it to the server's
297	     * current date when none was supplied, then roll it forward off weekends so a newly
298	     * registered owner always has a business-day registration date. Every value derived from it
299	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
300	     * date.
301	     */
302	    @PrePersist
303	    private void resolveRegistrationDate() {
304	        if (this.registrationDate == null) {
305	            this.registrationDate = LocalDate.now();
306	        }
307	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
308	    }
309	
310	    protected Set<Pet> getPetsInternal() {
311	        if (this.pets == null) {
312	            this.pets = new HashSet<>();
313	        }
314	        return this.pets;
315	    }
316	
317	    protected void setPetsInternal(Set<Pet> pets) {
318	        this.pets = pets;
319	    }
320	
321	    public List<Pet> getPets() {
322	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
323	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
324	        return Collections.unmodifiableList(sortedPets);
325	    }
326	
327	    public void setPets(List<Pet> pets) {
328	        this.pets = new HashSet<>(pets);
329	    }
330	
331	    public void addPet(Pet pet) {
332	        getPetsInternal().add(pet);
333	        pet.setOwner(this);
334	    }
335	
336	    /**
337	     * Return the Pet with the given name, or null if none found for this Owner.
338	     *
339	     * @param name to test
340	     * @return true if pet name is already in use
341	     */
342	    public Pet getPet(String name) {
343	        return getPet(name, false);
344	    }
345	
346	    /**
347	     * Return the Pet with the given name, or null if none found for this Owner.
348	     *
349	     * @param name to test
350	     * @return true if pet name is already in use
351	     */
352	    public Pet getPet(String name, boolean ignoreNew) {
353	        name = name.toLowerCase();
354	        for (Pet pet : getPetsInternal()) {
355	            if (!ignoreNew || !pet.isNew()) {
356	                String compName = pet.getName();
357	                compName = compName.toLowerCase();
358	                if (compName.equals(name)) {
359	                    return pet;
360	                }
361	            }
362	        }
363	        return null;
364	    }
365	
366	    public Pet getPet(Integer petId) {
367	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
368	    }
369	
370	    @Override
371	    public String toString() {
372	        return new ToStringCreator(this)
373	
374	            .append("id", this.getId())
375	            .append("new", this.isNew())
376	            .append("lastName", this.getLastName())
377	            .append("firstName", this.getFirstName())
378	            .append("address", this.address)
379	            .append("city", this.city)
380	            .append("telephone", this.telephone)
381	            .append("email", this.email)
382	            .toString();
383	    }
384	}
